-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset($data$[{"queue_id": "d9e22315-f85e-47bd-885f-1c77d779f7ca", "shop": "ChicDecorHK", "listing_id": "1721799800", "source_url": "https://www.etsy.com/listing/1721799800/handcrafted-scallop-shell-necklace-beach", "category": "Seashell Jewelry", "image_url": "https://i.etsystatic.com/32003756/r/il/ff1475/6058065789/il_1588xN.6058065789_con2.jpg", "destination_url": "https://www.etsy.com/listing/1721799800/handcrafted-scallop-shell-necklace-beach", "title": "Scallop Shell Necklace with White Ceramic Beads", "body": "A natural scallop shell pendant with gold-toned edging and white ceramic beads. Add a coastal detail to a simple outfit. From ChicDecorHK. Visit the original Etsy listing for options and current details.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "675399344058025061", "new_title": "Scallop Shell Necklace with White Ceramic Beads", "new_body": "A natural scallop shell pendant with gold-toned edging and white ceramic beads. Add a coastal detail to a simple outfit. From ChicDecorHK. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/32003756/r/il/ff1475/6058065789/il_1588xN.6058065789_con2.jpg", "checked_at": "2026-10-13T03:23:58.281Z"}, {"queue_id": "a92c074d-ec89-46c6-ac40-9e74bef11a49", "shop": "PearlsTreasuresArt", "listing_id": "1904477471", "source_url": "https://www.etsy.com/listing/1904477471/seashell-pearl-drop-earrings-gold-hoop", "category": "Seashell Jewelry", "image_url": "https://i.etsystatic.com/46725934/r/il/bdd26b/6846441847/il_1588xN.6846441847_myf4.jpg", "destination_url": "https://www.etsy.com/listing/1904477471/seashell-pearl-drop-earrings-gold-hoop", "title": "Seashell Drop Earrings for Coastal Style", "body": "Natural seashell drops and gold-toned hoops for coastal outfits. Explore the shell and pearl style options in the listing. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "675399344058025061", "new_title": "Seashell Drop Earrings for Coastal Style", "new_body": "Natural seashell drops and gold-toned hoops for coastal outfits. Explore the shell and pearl style options in the listing. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/46725934/r/il/bdd26b/6846441847/il_1588xN.6846441847_myf4.jpg", "checked_at": "2026-10-13T03:24:36.122Z"}, {"queue_id": "afa2833f-686e-41ed-9280-a8623307ee87", "shop": "PearlsTreasuresArt", "listing_id": "4339516931", "source_url": "https://www.etsy.com/listing/4339516931/handmade-sea-snail-shell-necklace-long", "category": "Seashell Jewelry", "image_url": "https://i.etsystatic.com/46725934/r/il/3d1a77/7090123133/il_1588xN.7090123133_e29l.jpg", "destination_url": "https://www.etsy.com/listing/4339516931/handmade-sea-snail-shell-necklace-long", "title": "Sea Snail Shell Necklace with Silver Seed Beads", "body": "A natural sea snail shell pendant suspended from delicate silver-colored seed beads. A long necklace for layered boho styling. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "675399344058025061", "new_title": "Sea Snail Shell Necklace with Silver Seed Beads", "new_body": "A natural sea snail shell pendant suspended from delicate silver-colored seed beads. A long necklace for layered boho styling. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/46725934/r/il/3d1a77/7090123133/il_1588xN.7090123133_e29l.jpg", "checked_at": "2026-10-13T03:24:46.019Z"}, {"queue_id": "aa7f0fae-ea20-4920-82c9-ea5f3309cc04", "shop": "PearlsTreasuresArt", "listing_id": "4348858512", "source_url": "https://www.etsy.com/listing/4348858512/pearl-tassel-seashell-earrings-handmade", "category": "Seashell Jewelry", "image_url": "https://i.etsystatic.com/46725934/r/il/bbb469/7093657750/il_1588xN.7093657750_43bm.jpg", "destination_url": "https://www.etsy.com/listing/4348858512/pearl-tassel-seashell-earrings-handmade", "title": "Seashell Earrings with Pearl Tassels", "body": "Sculpted natural shells and cascading pearl tassels create an ocean-inspired statement. Explore the asymmetrical design in the listing. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "handle": "cindyzhang62", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "675399344058025061", "new_title": "Seashell Earrings with Pearl Tassels", "new_body": "Sculpted natural shells and cascading pearl tassels create an ocean-inspired statement. Explore the asymmetrical design in the listing. From PearlsTreasuresArt. Visit the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/46725934/r/il/bbb469/7093657750/il_1588xN.7093657750_43bm.jpg", "checked_at": "2026-10-13T03:24:56.530Z"}]$data$::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,checked_at timestamptz);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_board_setup_operations where operation='p4-jewelry-20261019' and status='verified' and board_id='675399344058025061' and privacy='PUBLIC' and verified_at>now()-interval '24 hours') then raise exception 'Board verification missing'; end if;
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '30 days' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status='draft' and cv.status='draft' and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and p.last_seen_at=x.checked_at and p.listing_status='active' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id and h.platform='pinterest')
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 4 then raise exception 'Expected 4 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update content_variants cv set status='ready' from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;
update content_variants cv set title=x.title,body=x.body||' '||x.source_url,image_url=x.image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.product_id=q.product_id and cv.platform='facebook' and cv.status='draft' and not exists(select 1 from publish_history h where h.content_variant_id=cv.id);
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url) select queue_id,board_id,pinterest_publish_snapshot(queue_id),checked_at,source_url from reviewed_input;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft';
select json_build_object('listing_id',x.listing_id,'shop',x.shop,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',r.listing_checked_at) from reviewed_input x join publish_queue q on q.id=x.queue_id join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
